<body>

<canvas id="game3d"></canvas>

<div id="hud">
  <div class="hud-bar">
    <div class="hud-side left">
      <div class="hud-name" id="name-p">YOU</div>
      <div class="bar left"><div class="bar-fill player" id="hp-p" style="width:100%"></div><div class="bar-num" id="hp-p-num">100</div></div>
      <div class="stam left"><div class="stam-fill" id="stam-p" style="width:100%"></div></div>
    </div>
    <div class="center">
      <div class="round-num" id="round-num">R1</div>
      <div class="round-time" id="round-time">1:00</div>
      <div class="round-score" id="round-score">0-0</div>
    </div>
    <div class="hud-side right">
      <div class="hud-name" id="name-c">BRUNO</div>
      <div class="bar right"><div class="bar-fill cpu" id="hp-c" style="width:100%"></div><div class="bar-num" id="hp-c-num">100</div></div>
      <div class="stam right"><div class="stam-fill" id="stam-c" style="width:100%"></div></div>
    </div>
  </div>
</div>

<div id="round-banner"></div>
<div id="flash"></div>

<div class="screen active" id="screen-title">
  <h1>HEAVY HITTERS 3D</h1>
  <h2>â˜… Round 1 â˜…</h2>
  <p>Three rounds. One minute apiece. Drop your opponent or win on damage. Now in glorious 3D â€” third-person, two-arm combat.</p>
  <button class="btn" id="btn-fight">FIGHT</button>
  <div class="controls">
    <div><b>Move:</b> <span>W</span><span>A</span><span>S</span><span>D</span> &nbsp; <b>Block:</b> <span>SPACE</span> &nbsp; <b>Dodge:</b> <span>Q</span></div>
    <div><b>Jab:</b><span>J</span> <b>Cross:</b><span>K</span> <b>Hook:</b><span>U</span> <b>Uppercut:</b><span>I</span> <b>Overhand:</b><span>O</span></div>
    <div><b>Body:</b><span>B</span> <b>Liver:</b><span>V</span> <b>Straight:</b><span>Y</span> <b>Check Hook:</b><span>H</span></div>
    <div><b>Shovel:</b><span>G</span> <b>Corkscrew:</b><span>C</span> <b>Haymaker:</b><span>X</span></div>
    <div style="font-size:11px;color:#7a7060;margin-top:6px">Same-button presses alternate Left/Right arm.</div>
  </div>
</div>

<div class="screen" id="screen-end">
  <h1 id="end-title">VICTORY</h1>
  <h2 id="end-sub">By KO in Round 1</h2>
  <p id="end-stats"></p>
  <button class="btn" id="btn-rematch">REMATCH</button>
</div>

<div id="interlude">
  <h2 id="interlude-title">END OF ROUND</h2>
  <div class="diagrams" id="diagrams"></div>
  <div class="advice" id="advice"></div>
  <button class="btn" id="btn-continue">CONTINUE</button>
  <div class="timer" id="interlude-timer">Auto-advance in 6s</div>
</div>

<div id="touch-controls">
  <div class="touch-pad left">
    <span class="touch-btn empty"></span><span class="touch-btn" data-tk="w">â–²</span><span class="touch-btn empty"></span>
    <span class="touch-btn" data-tk="a">â—€</span><span class="touch-btn empty"></span><span class="touch-btn" data-tk="d">â–¶</span>
    <span class="touch-btn empty"></span><span class="touch-btn" data-tk="s">â–¼</span><span class="touch-btn empty"></span>
  </div>
  <div class="touch-pad right">
    <span class="touch-btn" data-tk="j">JAB</span>
    <span class="touch-btn" data-tk="k">CRS</span>
    <span class="touch-btn" data-tk="u">HK</span>
    <span class="touch-btn" data-tk="i">UP</span>
    <span class="touch-btn" data-tk="o">OVR</span>

    <span class="touch-btn" data-tk="y">STR</span>
    <span class="touch-btn" data-tk="h">CHK</span>
    <span class="touch-btn" data-tk="g">SHV</span>
    <span class="touch-btn" data-tk="c">CRK</span>
    <span class="touch-btn" data-tk="x">HAY</span>

    <span class="touch-btn" data-tk="b">BDY</span>
    <span class="touch-btn" data-tk="v">LIV</span>
    <span class="touch-btn empty"></span>
    <span class="touch-btn empty"></span>
    <span class="touch-btn blk" data-tk=" ">BLK</span>

    <span class="touch-btn empty"></span>
    <span class="touch-btn empty"></span>
    <span class="touch-btn empty"></span>
    <span class="touch-btn empty"></span>
    <span class="touch-btn empty"></span>
  </div>
</div>

<script>
'use strict';

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Config
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const RING_HALF = 3.0;
const FLOOR_Y = 0;

// Punch table.  Zone field is which body region the punch targets.
// For zone "RIBS" the side (LEFT_RIBS / RIGHT_RIBS) is decided by which arm threw it.
const PUNCH = {
  jab:        { dmg: 0.75, stam: 5,  range: 1.6, windup:0.06, active:0.06, recover:0.18, knockback:0.12, zone:'HEAD',  word:'POW',   col:'#ffd700', power:1, family:'jab' },
  cross:      { dmg: 1.38, stam:10,  range: 1.6, windup:0.10, active:0.07, recover:0.22, knockback:0.20, zone:'HEAD',  word:'CRACK', col:'#ff7a00', power:2, family:'cross' },
  hook:       { dmg: 1.5,  stam:12,  range: 1.4, windup:0.14, active:0.08, recover:0.28, knockback:0.22, zone:'HEAD',  word:'BAM',   col:'#ff7a00', power:2, family:'hook' },
  uppercut:   { dmg: 2.5,  stam:20,  range: 1.2, windup:0.22, active:0.10, recover:0.36, knockback:0.36, zone:'CHEST', word:'BOOM',  col:'#ff3838', power:3, family:'uppercut' },
  overhand:   { dmg: 2.0,  stam:16,  range: 1.5, windup:0.16, active:0.09, recover:0.30, knockback:0.28, zone:'HEAD',  word:'WHAM',  col:'#ff3838', power:3, family:'overhand' },
  bodyShot:   { dmg: 1.13, stam: 8,  range: 1.3, windup:0.10, active:0.07, recover:0.22, knockback:0.16, zone:'ABS',   word:'THUD',  col:'#ff9a3a', power:2, family:'body' },
  liverShot:  { dmg: 1.75, stam:14,  range: 1.3, windup:0.12, active:0.08, recover:0.26, knockback:0.22, zone:'LIVER', word:'OOF',   col:'#ff5e3a', power:2, family:'body' },
  straight:   { dmg: 1.25, stam: 9,  range: 1.7, windup:0.09, active:0.07, recover:0.22, knockback:0.18, zone:'HEAD',  word:'POW',   col:'#ffd700', power:2, family:'straight' },
  checkHook:  { dmg: 1.38, stam:10,  range: 1.4, windup:0.10, active:0.07, recover:0.20, knockback:0.18, zone:'HEAD',  word:'SNAP',  col:'#ff7a00', power:2, family:'hook' },
  shovelHook: { dmg: 1.63, stam:12,  range: 1.3, windup:0.12, active:0.08, recover:0.26, knockback:0.22, zone:'RIBS',  word:'CRUNCH',col:'#ff7a00', power:2, family:'hook' },
  corkscrew:  { dmg: 1.5,  stam:11,  range: 1.5, windup:0.10, active:0.08, recover:0.24, knockback:0.20, zone:'HEAD',  word:'TWIST', col:'#ff7a00', power:2, family:'cross' },
  haymaker:   { dmg: 3.0,  stam:26,  range: 1.3, windup:0.30, active:0.12, recover:0.50, knockback:0.46, zone:'HEAD',  word:'KO!!!', col:'#ff3838', power:3, family:'haymaker' },
};

// Which punches use the lead arm always, the rear arm always, or alternate L/R per press.
// "lead" / "rear" map to a fighter's lead/rear stance.  Player = lead-left orthodox.
const PUNCH_HAND = {
  jab:'lead', cross:'rear', hook:'alt', uppercut:'alt', overhand:'alt',
  bodyShot:'alt', liverShot:'alt', straight:'alt', checkHook:'lead',
  shovelHook:'alt', corkscrew:'alt', haymaker:'alt',
};

// Key â†’ punch.  Buttons that share L/R use the same key.
const KEY_PUNCH = {
  'j':'jab', 'k':'cross', 'u':'hook', 'i':'uppercut', 'o':'overhand',
  'b':'bodyShot', 'v':'liverShot', 'y':'straight', 'h':'checkHook',
  'g':'shovelHook', 'c':'corkscrew', 'x':'haymaker',
};

const ROUND_LEN = 60;
const TOTAL_ROUNDS = 3;

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Three.js scene
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const canvas = document.getElementById('game3d');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setClearColor(0x0a0a0a);
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 100);

// Camera state for third-person follow
const camPos = new THREE.Vector3(0, 3.0, 8.5);
const camTarget = new THREE.Vector3(0, 1.5, 0);
const camDesiredPos = new THREE.Vector3();
const camDesiredTarget = new THREE.Vector3();
camera.position.copy(camPos);
camera.lookAt(camTarget);

function fitRenderer(){
  const w = window.innerWidth, h = window.innerHeight;
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
}
window.addEventListener('resize', fitRenderer);
fitRenderer();

// Lighting
scene.add(new THREE.AmbientLight(0xffffff, 0.55));
const sun = new THREE.DirectionalLight(0xfff2c8, 0.85);
sun.position.set(6, 14, 8);
scene.add(sun);
const spot = new THREE.PointLight(0xfff2c8, 0.8, 16);
spot.position.set(0, 5, 0);
scene.add(spot);
const back = new THREE.PointLight(0xff7a3a, 0.35, 18);
back.position.set(0, 3, -5);
scene.add(back);
const backBaseIntensity = 0.35;
let backPulse = 0;

// Sky
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(50, 24, 12),
  new THREE.MeshBasicMaterial({ color: 0x1a0d0d, side: THREE.BackSide })
);
scene.add(sky);

// Crowd
function buildCrowd(){
  const grp = new THREE.Group();
  for (let i = 0; i < 200; i++){
    const a = (i / 200) * Math.PI * 2;
    const r = 7.5 + Math.random() * 2.5;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    const tier = Math.floor(Math.random() * 3);
    const yBase = 0.5 + tier * 0.6;
    const col = Math.random() < 0.4 ? 0x331a1a : (Math.random() < 0.5 ? 0x222 : 0x442222);
    const body = new THREE.Mesh(
      new THREE.CylinderGeometry(0.18, 0.18, 0.55, 6),

      new THREE.MeshLambertMaterial({ color: col })
    );
    body.position.set(x, yBase + 0.27, z);
    grp.add(body);
    const head = new THREE.Mesh(
      new THREE.SphereGeometry(0.13, 6, 5),
      new THREE.MeshLambertMaterial({ color: 0xc88a55 })
    );
    head.position.set(x, yBase + 0.65, z);
    grp.add(head);
  }
  scene.add(grp);
  return grp;
}
const crowd = buildCrowd();

// Arena floor
const arenaFloor = new THREE.Mesh(
  new THREE.CircleGeometry(15, 48),
  new THREE.MeshLambertMaterial({ color: 0x0d0606 })
);
arenaFloor.rotation.x = -Math.PI/2;
arenaFloor.position.y = -0.02;
scene.add(arenaFloor);

// Ring
function buildRing(){
  const grp = new THREE.Group();
  const base = new THREE.Mesh(
    new THREE.BoxGeometry(7.4, 0.4, 7.4),
    new THREE.MeshLambertMaterial({ color: 0x2a1a14 })
  );
  base.position.y = -0.2;
  grp.add(base);
  const apronCanvas = document.createElement('canvas');
  apronCanvas.width = 256; apronCanvas.height = 32;
  const ax = apronCanvas.getContext('2d');
  ax.fillStyle = '#cc0000'; ax.fillRect(0, 0, 256, 32);
  ax.fillStyle = '#ffd700';
  ax.font = 'bold 22px Arial Black, sans-serif';
  ax.textAlign = 'center'; ax.textBaseline = 'middle';
  ax.fillText('â˜… HEAVY HITTERS â˜… HEAVY HITTERS â˜… HEAVY HITTERS â˜…', 128, 17);
  const apronTex = new THREE.CanvasTexture(apronCanvas);
  apronTex.wrapS = THREE.RepeatWrapping;
  apronTex.repeat.x = 2;
  const apron = new THREE.Mesh(
    new THREE.BoxGeometry(7.45, 0.4, 7.45),
    new THREE.MeshLambertMaterial({ map: apronTex })
  );
  apron.position.y = -0.2;
  apron.scale.set(1.001, 1.0, 1.001);
  grp.add(apron);
  const matCanvas = document.createElement('canvas');
  matCanvas.width = 512; matCanvas.height = 512;
  const mc = matCanvas.getContext('2d');
  mc.fillStyle = '#1a4a8a'; mc.fillRect(0, 0, 512, 512);
  mc.strokeStyle = '#ffd700'; mc.lineWidth = 8;
  mc.beginPath(); mc.arc(256, 256, 100, 0, Math.PI*2); mc.stroke();
  mc.fillStyle = '#ffd700';
  mc.font = 'bold 64px Arial Black, sans-serif';
  mc.textAlign = 'center'; mc.textBaseline = 'middle';
  mc.fillText('HH', 256, 256);
  mc.fillStyle = '#cc0000';
  mc.beginPath(); mc.moveTo(0, 0); mc.lineTo(140, 0); mc.lineTo(0, 140); mc.fill();
  mc.beginPath(); mc.moveTo(512, 512); mc.lineTo(372, 512); mc.lineTo(512, 372); mc.fill();
  mc.fillStyle = '#0066cc';
  mc.beginPath(); mc.moveTo(512, 0); mc.lineTo(372, 0); mc.lineTo(512, 140); mc.fill();
  mc.beginPath(); mc.moveTo(0, 512); mc.lineTo(140, 512); mc.lineTo(0, 372); mc.fill();
  const matTex = new THREE.CanvasTexture(matCanvas);
  const mat = new THREE.Mesh(
    new THREE.PlaneGeometry(6, 6),
    new THREE.MeshLambertMaterial({ map: matTex })
  );
  mat.rotation.x = -Math.PI/2;
  mat.position.y = 0.005;
  grp.add(mat);
  const postPositions = [[ 3.1, 3.1], [-3.1, 3.1], [-3.1, -3.1], [3.1, -3.1]];
  for (const [px, pz] of postPositions){
    const post = new THREE.Mesh(
      new THREE.CylinderGeometry(0.08, 0.10, 1.85, 8),
      new THREE.MeshLambertMaterial({ color: 0x3a2614 })
    );
    post.position.set(px, 0.92, pz);
    grp.add(post);
    const cap = new THREE.Mesh(
      new THREE.BoxGeometry(0.32, 0.18, 0.32),
      new THREE.MeshLambertMaterial({ color: 0xffd700 })
    );
    cap.position.set(px, 1.93, pz);
    grp.add(cap);
    const pad = new THREE.Mesh(
      new THREE.CylinderGeometry(0.16, 0.16, 1.6, 8),
      new THREE.MeshLambertMaterial({ color: (px > 0 ? 0x0066cc : 0xcc0000) })
    );
    pad.position.set(px, 0.85, pz);
    grp.add(pad);
  }
  const ropeColors = [0xcc0000, 0xffd700, 0x0066cc];
  for (let lvl = 0; lvl < 3; lvl++){
    const y = 0.85 + lvl * 0.42;
    const col = ropeColors[lvl];
    const frontRope = new THREE.Mesh(
      new THREE.CylinderGeometry(0.04, 0.04, 6.2, 8),
      new THREE.MeshLambertMaterial({ color: col })
    );
    frontRope.rotation.z = Math.PI/2;
    frontRope.position.set(0, y, 3.1);
    grp.add(frontRope);
    const backRope = frontRope.clone();
    backRope.position.set(0, y, -3.1);
    grp.add(backRope);
    const leftRope = new THREE.Mesh(
      new THREE.CylinderGeometry(0.04, 0.04, 6.2, 8),
      new THREE.MeshLambertMaterial({ color: col })
    );
    leftRope.rotation.x = Math.PI/2;
    leftRope.position.set(-3.1, y, 0);
    grp.add(leftRope);
    const rightRope = leftRope.clone();
    rightRope.position.set(3.1, y, 0);
    grp.add(rightRope);
  }
  scene.add(grp);
  return grp;
}
const ring = buildRing();

// Overhead lamps
for (const pos of [[-2, 5, -2], [2, 5, -2], [-2, 5, 2], [2, 5, 2]]){
  const lampHousing = new THREE.Mesh(
    new THREE.ConeGeometry(0.3, 0.4, 8),
    new THREE.MeshLambertMaterial({ color: 0x222 })
  );
  lampHousing.position.set(...pos);
  scene.add(lampHousing);
  const lamp = new THREE.Mesh(
    new THREE.SphereGeometry(0.14, 8, 6),
    new THREE.MeshBasicMaterial({ color: 0xfff2c8 })
  );
  lamp.position.set(pos[0], pos[1] - 0.2, pos[2]);
  scene.add(lamp);
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Boxer rig (3D)
//  Default-facing direction is +X.  Facing flipped via root.rotation.y.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function createBoxer3D(opts){
  const root = new THREE.Group();
  const skinMat   = new THREE.MeshLambertMaterial({ color: opts.skin });
  const trunkMat  = new THREE.MeshLambertMaterial({ color: opts.trunks });
  const beltMat   = new THREE.MeshLambertMaterial({ color: 0xffd700 });
  const bootMat   = new THREE.MeshLambertMaterial({ color: 0x111111 });
  const gloveMat  = new THREE.MeshLambertMaterial({ color: opts.gloveColor });
  const cuffMat   = new THREE.MeshLambertMaterial({ color: 0xffffff });
  const stripeMat = new THREE.MeshLambertMaterial({ color: 0xffd700 });
  const hairMat   = new THREE.MeshLambertMaterial({ color: 0x1a0d0d });
  const eyeMat    = new THREE.MeshBasicMaterial({ color: 0x000 });
  const detailMat = new THREE.MeshLambertMaterial({ color: 0x6a4a30 });
  const mouthMat  = new THREE.MeshLambertMaterial({ color: 0x4a1a1a });
  const laceMat   = new THREE.MeshLambertMaterial({ color: 0xffffff });

  // â•�â•�â•� LEGS â•�â•�â•�
  function buildLeg(side){
    const grp = new THREE.Group();
    grp.position.set(0, 0.92, side * 0.13);
    const thighTrunk = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.135, 0.32, 12), trunkMat);
    thighTrunk.position.y = -0.15;
    grp.add(thighTrunk);
    const thighSkin = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.115, 0.18, 10), skinMat);
    thighSkin.position.y = -0.40;
    grp.add(thighSkin);
    const knee = new THREE.Mesh(new THREE.SphereGeometry(0.105, 8, 6), skinMat);
    knee.position.y = -0.51;
    grp.add(knee);
    // Knee pivot group â€” lower leg rotates around this joint
    const kneeGroup = new THREE.Group();
    kneeGroup.position.y = -0.51;
    grp.add(kneeGroup);
    const calf = new THREE.Mesh(new THREE.CylinderGeometry(0.105, 0.085, 0.32, 10), skinMat);
    calf.position.y = -0.17;   // relative to kneeGroup
    kneeGroup.add(calf);
    const boot = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.12, 0.32), bootMat);
    boot.position.set(0.04, -0.37, 0);  // relative to kneeGroup
    kneeGroup.add(boot);
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.21, 0.02, 0.33), beltMat);
    stripe.position.set(0.04, -0.33, 0); // relative to kneeGroup
    kneeGroup.add(stripe);
    root.add(grp);
    return { grp, kneeGroup };
  }
  const legLData = buildLeg(-1);
  const legRData = buildLeg(+1);
  const legL = legLData.grp;
  const legR = legRData.grp;

  // â•�â•�â•� HIPS â•�â•�â•�
  const hipsGroup = new THREE.Group();
  hipsGroup.position.y = 0;
  root.add(hipsGroup);
  const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.20, 0.18, 0.10, 14), beltMat);
  belt.position.y = 0.95;
  hipsGroup.add(belt);

  // â•�â•�â•� TORSO â•�â•�â•� (group so we can lean it)
  const torso = new THREE.Group();
  torso.position.y = 0;
  root.add(torso);

  const chest = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.36, 0.55), skinMat);
  chest.position.y = 1.30;
  torso.add(chest);
  const waist = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.20, 0.44), skinMat);
  waist.position.y = 1.04;
  torso.add(waist);
  const rib = new THREE.Mesh(new THREE.BoxGeometry(0.30, 0.06, 0.50), skinMat);
  rib.position.y = 1.14;
