  // Each arm has: shoulder (group, rotates at the shoulder joint),
  //               forearmRot (group at end of upper arm, rotates at the elbow),
  //               glove (group at end of forearm).
  function buildArm(side){
    const shoulder = new THREE.Group();
    shoulder.position.set(0, 1.50, side * 0.22);
    // Bicep / upper arm
    const upper = new THREE.Mesh(
      new THREE.CylinderGeometry(0.085, 0.07, 0.32, 10),
