  // â•�â•�â•� ARMS â€” 4-group chain: shoulderGrp â†’ elbowGrp â†’ forearmPivot â†’ wristGrp â•�â•�â•�
  // Arms attach to thoracic so they follow spine twist naturally.
  function buildArm(side){
