    case 'bodyShot': {
      // Aimed at ribs/stomach: shoulder DROPS (sX negative), arm drives downward-forward
      sZ = gSZ - ext * 0.85;
      sY = -sign * (0.30 + ext * 0.70);
      sX = gSX - ext * 0.55;                        // shoulder TILTS DOWNWARD (negative) âœ“
      eZ = Math.max(0.25, gEZ - ext * 0.70);        // arm extends but not fully (downward angle)
      pY = -0.28 + ext * 1.05;                      // pronates as it lands
      wX = 0.20 * ext;                              // wrist flexes slightly (knuckles into ribs)
      wZ = 0;
      break;
    }
    case 'liverShot': {
      // Targets under right rib cage: drops level, drives INWARD with ulnar deviation
      sZ = gSZ - ext * 0.95;
      sY = -sign * (0.22 + ext * 0.62);
      sX = gSX - ext * 0.62;                        // even bigger downward tilt than bodyShot âœ“
      eZ = Math.max(0.55, gEZ - ext * 0.55);        // arm bends a bit at the hip (hook-into-liver)
      pY = -0.28 + ext * 1.20;
      wX = 0.14 * ext;
      wZ = sign * ext * 0.18;                       // strong ulnar deviation (drives into liver) âœ“
      break;
    }
    case 'shovelHook': {
      // Mix of hook (horizontal) and uppercut (vertical) â†’ diagonal upward path
      const shWind = Math.min(1, ext / 0.25);
      const shCrash = Math.max(0, (ext - 0.25) / 0.75);
      sZ = gSZ - ext * 1.15;                        // mid-elevation drop (between hook & uppercut)
      sY = -sign * (0.40 + ext * 0.95);             // some horizontal sweep
      sX = gSX - shWind * 0.28 + shCrash * 0.65;    // dips on windup â†’ up & forward (diagonal)
      eZ = Math.max(0.85, gEZ - ext * 0.30);        // HINGE: stays bent (â‰¥0.85, hook trait) âœ“
      pY = -0.28 - ext * 0.15;                      // slight supination (between hook & uppercut)
      wX = -0.10 * ext;
      wZ = sign * ext * 0.10;
      break;
    }
    case 'corkscrew': {
      // Straight punch with EXTRA forearm twist past full pronation
      sZ = gSZ - ext * 1.30;
      sY = -sign * (0.22 + ext * 0.78);
      sX = gSX + ext * 0.50;
      eZ = gEZ - ext * (gEZ - 0.06);                // HINGE: extends fully (like jab)
      pY = -0.28 + ext * 2.05;                      // PIVOT: WAY past pronation = corkscrew twist âœ“
      wX = 0.05 - ext * 0.10;
      wZ = -sign * ext * 0.22;                      // wrist deviation reinforces the twist
      break;
    }
    case 'haymaker': {
      // Huge wind-back then crashing forward swing with full body weight
      // windup (ext<0.25): shoulder cocks BACK âœ“; crash (ext>0.25): swings around to impact
      const wind = Math.min(1, ext / 0.25);
      const crash = Math.max(0, (ext - 0.25) / 0.75);
      sZ = gSZ + wind * 0.35 - crash * 1.30;        // arm lifts on windup, drops on crash
      sY = -sign * (-0.65 * wind + (0.95 + crash * 1.50));  // shoulder rotates BACKWARD then sweeps forward âœ“
      sX = gSX + wind * 0.55 - crash * 0.20;        // pulls back, then comes forward
      eZ = Math.min(1.95, gEZ + wind * 0.30) - crash * 0.90;  // bends on windup, extends on crash
      pY = -0.28 - wind * 0.60 + crash * 1.80;      // big supination on windup â†’ full pronation on impact
      wX = -0.15 * wind + 0.05 * crash;
      wZ = -sign * 0.14 * crash;
      break;
    }
  }

  // Hard-clamp the hinge so it cannot exceed legal ROM (rule #1)
  if (eZ > 2.0) eZ = 2.0;
  if (eZ < 0)   eZ = 0;

  arm.shoulderGrp.rotation.set(sX, sY, sZ);
  arm.elbowGrp.rotation.set(0, 0, eZ);      // HINGE: only Z
  arm.forearmPivot.rotation.set(0, pY, 0);  // PIVOT: only Y
  arm.wristGrp.rotation.set(wX, 0, wZ);     // CONDYLOID: X + Z
}

